export function normalizePercent(text, subject) {
  let result = ''
  let i = 0
  while (i < text.length) {
    if (text[i] === '%') {
      // Check if there are at least 2 more characters for the hex digits
      if (i + 2 >= text.length) {
        throw new UriError(`${subject} has a truncated percent-encoding`)
      }
      // Get the next 2 characters
      const hex = text.slice(i + 1, i + 3)
      // Check if they are hexadecimal digits
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new UriError(`${subject} has a truncated percent-encoding`)
      }
      // Decode the character
      const decoded = String.fromCharCode(parseInt(hex, 16))
      // Check if it's unreserved: if so, use the decoded character; otherwise keep encoded with uppercase hex
      if (UNRESERVED.test(decoded)) {
        result += decoded
      } else {
        result += `%${hex.toUpperCase()}`
      }
      i += 3
    } else {
      result += text[i]
      i++
    }
  }
  return result
}

